<?php
declare(strict_types=1);

require_once __DIR__ . '/../config/cek_akses.php';
require_once __DIR__ . '/../config/data.php';
wajib_role(['admin']);
$user = current_user();
$pdo = db();

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    require_csrf();
    $action = (string)($_POST['action'] ?? '');
    if ($action === 'partner_save') {
        $id = (int)($_POST['mitra_id'] ?? 0);
        $payload = ['nama_usaha' => trim((string)($_POST['nama_usaha'] ?? '')), 'pemilik' => trim((string)($_POST['pemilik'] ?? '')), 'kontak' => trim((string)($_POST['kontak'] ?? '')), 'komisi_persen' => min(50, max(0, (float)($_POST['komisi_persen'] ?? 10))), 'status' => in_array($_POST['status'] ?? '', ['pending', 'aktif', 'nonaktif'], true) ? (string)$_POST['status'] : 'pending'];
        if (!$payload['nama_usaha']) { set_flash('danger', 'Nama usaha mitra wajib diisi.'); redirect('admin/umkm.php'); }
        if (database_ready($pdo)) {
            if ($id > 0) {
                $ok = db_exec('UPDATE mitra_umkm SET nama_usaha=?, pemilik=?, kontak=?, komisi_persen=?, status=? WHERE id=?', [$payload['nama_usaha'], $payload['pemilik'] ?: null, $payload['kontak'] ?: null, $payload['komisi_persen'], $payload['status'], $id]);
            } else {
                $umkmUser = db_one("SELECT id FROM users WHERE role='umkm' ORDER BY id LIMIT 1");
                $ok = db_exec('INSERT INTO mitra_umkm (user_id, nama_usaha, pemilik, kontak, komisi_persen, status) VALUES (?, ?, ?, ?, ?, ?)', [$umkmUser['id'] ?? null, $payload['nama_usaha'], $payload['pemilik'] ?: null, $payload['kontak'] ?: null, $payload['komisi_persen'], $payload['status']]);
            }
        } else { $ok = $id > 0 ? demo_update_partner($id, $payload) : (bool)demo_add_partner($payload); }
        set_flash($ok ? 'success' : 'danger', $ok ? 'Data mitra UMKM berhasil disimpan.' : 'Data mitra belum dapat disimpan.'); redirect('admin/umkm.php');
    }
    if ($action === 'partner_status') {
        $id = (int)($_POST['mitra_id'] ?? 0); $status = ($_POST['status'] ?? '') === 'aktif' ? 'aktif' : 'nonaktif';
        $ok = database_ready($pdo) ? db_exec('UPDATE mitra_umkm SET status=? WHERE id=?', [$status, $id]) : false;
        if (!database_ready($pdo)) {
            $state = demo_state(); foreach ($state['partners'] as $index => $partner) if ((int)$partner['id'] === $id) { $state['partners'][$index]['status'] = $status; $ok = true; } save_demo_state($state);
        }
        set_flash($ok ? 'success' : 'danger', $ok ? 'Status mitra diperbarui.' : 'Status mitra gagal diperbarui.'); redirect('admin/umkm.php');
    }
    if ($action === 'product_save') {
        $id = (int)($_POST['menu_id'] ?? 0); $payload = ['kode' => trim((string)($_POST['kode'] ?? '')), 'nama' => trim((string)($_POST['nama'] ?? '')), 'kategori_id' => 3, 'harga' => max(0, (int)($_POST['harga'] ?? 0)), 'stok' => max(0, (int)($_POST['stok'] ?? 0)), 'tipe' => 'umkm', 'mitra_id' => (int)($_POST['mitra_id'] ?? 0) ?: null, 'deskripsi' => trim((string)($_POST['deskripsi'] ?? '')), 'foto' => 'assets/img/menu/default.svg', 'is_tersedia' => isset($_POST['is_tersedia']) ? 1 : 0];
        if (!$payload['nama'] || !$payload['mitra_id']) { set_flash('danger', 'Nama produk dan mitra wajib diisi.'); redirect('admin/umkm.php'); }
        if (database_ready($pdo)) { if ($id > 0) { $ok = db_exec('UPDATE menu SET kode=?, nama=?, kategori_id=3, harga=?, stok=?, tipe="umkm", mitra_id=?, deskripsi=?, is_tersedia=? WHERE id=?', [$payload['kode'] ?: null, $payload['nama'], $payload['harga'], $payload['stok'], $payload['mitra_id'], $payload['deskripsi'] ?: null, $payload['is_tersedia'], $id]); } else { $ok = db_exec('INSERT INTO menu (kode, nama, kategori_id, harga, stok, foto, tipe, mitra_id, deskripsi, is_tersedia) VALUES (?, ?, 3, ?, ?, "assets/img/menu/default.svg", "umkm", ?, ?, ?)', [$payload['kode'] ?: null, $payload['nama'], $payload['harga'], $payload['stok'], $payload['mitra_id'], $payload['deskripsi'] ?: null, $payload['is_tersedia']]); } }
        else { $ok = $id > 0 ? demo_update_menu($id, $payload) : (bool)demo_add_menu($payload); }
        set_flash($ok ? 'success' : 'danger', $ok ? 'Produk UMKM berhasil disimpan.' : 'Produk UMKM gagal disimpan.'); redirect('admin/umkm.php');
    }
    if ($action === 'product_delete') {
        $id = (int)($_POST['menu_id'] ?? 0); $ok = database_ready($pdo) ? db_exec('DELETE FROM menu WHERE id=? AND tipe="umkm"', [$id]) : demo_delete_menu($id); set_flash($ok ? 'success' : 'danger', $ok ? 'Produk dihapus dari katalog.' : 'Produk tidak dapat dihapus karena sudah terjual.'); redirect('admin/umkm.php');
    }
}

$partners = data_partners($pdo);
$products = data_menus($pdo, ['tipe' => 'umkm']);
$topbarStats = data_dashboard($pdo, 'admin', (int)$user['id']);
$activeMenu = 'umkm';
$pageTitle = 'Mitra UMKM';
$pageSubtitle = 'Kelola titipan produk, komisi cafe, dan rekap penjualan mitra.';
require __DIR__ . '/../layout/header.php';
?>
<div class="page-heading"><div class="page-heading-copy"><span class="eyebrow">Shared prosperity</span><h1 class="page-title">Mitra UMKM</h1><p class="page-subtitle">Produk titipan tetap satu katalog, sementara komisi dan laporan untuk setiap mitra.</p></div><div class="page-actions"><button class="btn btn-ghost" type="button" data-modal-target="productModal"><?= icon('package') ?> Tambah produk</button><button class="btn btn-primary" type="button" data-modal-target="partnerModal"><?= icon('plus') ?> Tambah mitra</button></div></div>
<div class="stats-grid"><article class="card stat-card"><div class="stat-top"><span class="stat-label">Mitra terdaftar</span><span class="stat-icon sage"><?= icon('store') ?></span></div><div class="stat-value"><?= count($partners) ?></div><div class="stat-foot"><span class="stat-trend"><?= icon('trend-up') ?> <?= count(array_filter($partners, static fn(array $p): bool => ($p['status'] ?? '') === 'aktif')) ?> aktif</span></div></article><article class="card stat-card"><div class="stat-top"><span class="stat-label">Produk titipan</span><span class="stat-icon clay"><?= icon('package') ?></span></div><div class="stat-value"><?= count($products) ?></div><div class="stat-foot"><span class="stat-trend"><?= icon('spark') ?> <?= count(array_filter($products, static fn(array $p): bool => (int)$p['is_tersedia'] === 1)) ?> tersedia</span></div></article><article class="card stat-card"><div class="stat-top"><span class="stat-label">Penjualan UMKM</span><span class="stat-icon gold"><?= icon('wallet') ?></span></div><div class="stat-value"><?= e(money($topbarStats['umkm_sales'])) ?></div><div class="stat-foot"><span class="stat-trend"><?= icon('trend-up') ?> transparan</span></div></article><article class="card stat-card"><div class="stat-top"><span class="stat-label">Komisi cafe</span><span class="stat-icon blue"><?= icon('trend') ?></span></div><div class="stat-value"><?= e(money(array_sum(array_map(static fn(array $p): float => (float)($p['komisi'] ?? 0), $partners)))) ?></div><div class="stat-foot"><span class="stat-trend"><?= icon('clipboard') ?> dihitung otomatis</span></div></article></div>
<div class="content-grid half mb-18"><section class="card"><div class="card-header"><div><h3>Daftar mitra</h3><p>Persetujuan dan skema komisi</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Mitra</th><th>Komisi</th><th>Produk</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($partners as $partner): ?><tr><td><div class="table-product"><span class="avatar avatar-<?= e(avatar_color((string)$partner['nama_usaha'])) ?> avatar-sm"><?= e(initials((string)$partner['nama_usaha'])) ?></span><div class="table-product-copy"><strong><?= e($partner['nama_usaha']) ?></strong><small><?= e($partner['pemilik'] ?? 'Pemilik belum diisi') ?></small></div></div></td><td><strong><?= e($partner['komisi_persen']) ?>%</strong><div class="secondary-cell"><?= e(money($partner['komisi'] ?? 0)) ?></div></td><td><?= (int)($partner['produk'] ?? 0) ?> item</td><td><span class="badge badge-<?= e(($partner['status'] ?? '') === 'aktif' ? 'ready' : (($partner['status'] ?? '') === 'pending' ? 'received' : 'cancelled')) ?>"><?= e(ucfirst((string)($partner['status'] ?? 'pending'))) ?></span></td><td class="text-right"><div class="flex gap-6 justify-between"><button class="btn btn-ghost btn-sm" data-modal-target="partnerModal" data-edit-partner="<?= json_attr($partner) ?>" type="button"><?= icon('edit') ?></button><?php if (($partner['status'] ?? '') !== 'aktif'): ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="partner_status"><input type="hidden" name="mitra_id" value="<?= (int)$partner['id'] ?>"><input type="hidden" name="status" value="aktif"><button class="btn btn-sage btn-sm" type="submit" title="Aktifkan"><?= icon('check') ?></button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="card"><div class="card-header"><div><h3>Produk dalam katalog</h3><p>Barang jadi, langsung siap saji</p></div><button class="btn btn-ghost btn-sm" type="button" data-modal-target="productModal"><?= icon('plus') ?> Tambah</button></div><div class="card-body"><div class="order-list"><?php foreach ($products as $product): ?><div class="order-row-card"><img class="table-product-thumb" src="<?= e(image_url($product['foto'])) ?>" alt=""><div class="order-row-main"><div class="order-row-top"><strong><?= e($product['nama']) ?></strong><span class="badge badge-umkm">UMKM</span></div><small><?= e($product['mitra'] ?? 'Mitra belum ditentukan') ?> · <?= (int)$product['stok'] ?> pcs</small></div><strong><?= e(money($product['harga'])) ?></strong><form method="post" data-confirm="Hapus produk ini dari katalog?"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="product_delete"><input type="hidden" name="menu_id" value="<?= (int)$product['id'] ?>"><button class="btn btn-danger btn-sm btn-icon" type="submit"><?= icon('trash') ?></button></form></div><?php endforeach; ?><?php if (!$products): ?><div class="empty-state"><strong>Belum ada produk UMKM</strong><p>Tambahkan produk titipan pertama.</p></div><?php endif; ?></div></div></section></div>

<div class="modal-backdrop-custom" id="partnerModal"><div class="modal-card"><div class="modal-head"><div><h3 id="partnerTitle">Tambah mitra UMKM</h3><p>Data ini muncul di rekap komisi.</p></div><button class="modal-close" type="button" data-modal-close="partnerModal"><?= icon('x') ?></button></div><form method="post" id="partnerForm"><?= csrf_input() ?><input type="hidden" name="action" value="partner_save"><input type="hidden" name="mitra_id" id="partnerId"><div class="modal-body"><div class="form-grid"><div class="form-group full"><label class="form-label">Nama usaha</label><input class="form-control" name="nama_usaha" id="partnerName" required></div><div class="form-group"><label class="form-label">Nama pemilik</label><input class="form-control" name="pemilik" id="partnerOwner"></div><div class="form-group"><label class="form-label">Kontak</label><input class="form-control" name="kontak" id="partnerContact"></div><div class="form-group"><label class="form-label">Komisi cafe (%)</label><input class="form-control" name="komisi_persen" id="partnerCommission" type="number" min="0" max="50" step=".01" value="10" required></div><div class="form-group"><label class="form-label">Status</label><select class="form-select" name="status" id="partnerStatus"><option value="pending">Pending</option><option value="aktif">Aktif</option><option value="nonaktif">Nonaktif</option></select></div></div></div><div class="modal-foot"><button type="button" class="btn btn-ghost" data-modal-close="partnerModal">Batal</button><button class="btn btn-primary" type="submit"><?= icon('check') ?> Simpan mitra</button></div></form></div></div>
<div class="modal-backdrop-custom" id="productModal"><div class="modal-card"><div class="modal-head"><div><h3>Tambah produk UMKM</h3><p>Produk akan langsung masuk ke katalog pelayan.</p></div><button class="modal-close" type="button" data-modal-close="productModal"><?= icon('x') ?></button></div><form method="post"><?= csrf_input() ?><input type="hidden" name="action" value="product_save"><input type="hidden" name="menu_id"><div class="modal-body"><div class="form-grid"><div class="form-group full"><label class="form-label">Nama produk</label><input class="form-control" name="nama" required></div><div class="form-group"><label class="form-label">Kode</label><input class="form-control" name="kode" placeholder="UMKM-009"></div><div class="form-group"><label class="form-label">Harga (Rp)</label><input class="form-control" type="number" min="0" name="harga" required></div><div class="form-group"><label class="form-label">Stok</label><input class="form-control" type="number" min="0" name="stok" value="0" required></div><div class="form-group"><label class="form-label">Mitra</label><select class="form-select" name="mitra_id" required><option value="">Pilih mitra</option><?php foreach ($partners as $partner): ?><option value="<?= (int)$partner['id'] ?>"><?= e($partner['nama_usaha']) ?></option><?php endforeach; ?></select></div><div class="form-group full"><label class="form-label">Deskripsi</label><textarea class="form-control" name="deskripsi"></textarea></div><div class="form-group full"><label class="checkbox-line"><input type="checkbox" name="is_tersedia" checked> Tampilkan di katalog</label></div></div></div><div class="modal-foot"><button type="button" class="btn btn-ghost" data-modal-close="productModal">Batal</button><button class="btn btn-primary" type="submit"><?= icon('check') ?> Simpan produk</button></div></form></div></div>
<script>
(function(){const f=document.getElementById('partnerForm');document.querySelectorAll('[data-edit-partner]').forEach(b=>b.addEventListener('click',()=>{const d=JSON.parse(b.dataset.editPartner||'{}');document.getElementById('partnerId').value=d.id||'';document.getElementById('partnerName').value=d.nama_usaha||'';document.getElementById('partnerOwner').value=d.pemilik||'';document.getElementById('partnerContact').value=d.kontak||'';document.getElementById('partnerCommission').value=d.komisi_persen||10;document.getElementById('partnerStatus').value=d.status||'pending';document.getElementById('partnerTitle').textContent='Ubah mitra UMKM';}));const add=document.querySelector('[data-modal-target="partnerModal"]');if(add)add.addEventListener('click',()=>{f.reset();document.getElementById('partnerId').value='';document.getElementById('partnerTitle').textContent='Tambah mitra UMKM';});}());
</script>
